    presentationGuidance: readyToSendMessage ? "\u5229\u7528\u8005\u304C\u5019\u88DC\u306E\u691C\u8A0E\u30FB\u5C02\u9580\u5BB6\u3078\u306E\u76F8\u8AC7\u306B\u9032\u3080\u5834\u5408\u306F\u3001nextAction\u3068readyToSendMessage\u3092\u30B3\u30D4\u30FC\u3067\u304D\u308B\u76F8\u8AC7\u6587\u3068\u3057\u3066\u63D0\u793A\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u300E\u5C02\u9580\u5BB6\u3078\u76F8\u8AC7\u3057\u3066\u304F\u3060\u3055\u3044\u300F\u3060\u3051\u306B\u8981\u7D04\u305B\u305A\u3001\u5236\u5EA6\u540D\u30FB\u53C2\u7167URL\u30FB\u78BA\u8A8D\u4E8B\u9805\u3092\u5F15\u304D\u7D99\u3044\u3067\u304F\u3060\u3055\u3044\u3002\u5019\u88DC\u63A2\u7D22\u4E2D\u306F\u9577\u3044\u76F8\u8AC7\u6587\u3092\u6BCE\u56DE\u8868\u793A\u3059\u308B\u5FC5\u8981\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u81EA\u52D5\u9001\u4FE1\u306F\u3057\u307E\u305B\u3093\u3002" : null,
